    public void forAtomicBlockHelper(Block x) {
        mv.visitMethodInsn(INVOKESTATIC, 
                           "com/sun/fortress/runtimeSystem/BaseTask", 
                           "startTransaction", "()V");     
        forBlockHelper(x);
        mv.visitMethodInsn(INVOKESTATIC, "com/sun/fortress/runtimeSystem/BaseTask", 
                           "endTransaction", "()V");
    }

